100	
101	export function GameLogo({
102	  family,
103	  size = 48,
104	  className = "",
105	}: {
106	  family: string;
107	  /** Tile edge length in px. Default 48. */
108	  size?: number;
109	  className?: string;
110	}) {
111	  const visual = GAME_VISUAL[family] ?? NEUTRAL;
112	
113	  // Candidate srcs in resolution order. Owner drop-in first, bundled asset last.
114	  // Owner drop-ins live in /logos/games/. They uploaded PNGs, so render the .png
115	  // FIRST (it exists for all six families → correct SSR image, no 404/broken-image
116	  // flash), then an optional .svg override, then the bundled /games/* fallback.
117	  const candidates = [
118	    `/logos/games/${family}.png`,
119	    `/logos/games/${family}.svg`,
120	    KNOWN_ASSET[family],
121	  ].filter(Boolean) as string[];
122	
123	  const [idx, setIdx] = useState(0);
124	  const exhausted = idx >= candidates.length;
125	  const src = candidates[idx];
126	  const pad = Math.max(4, Math.round(size * 0.16));
127	
128	  return (
129	    <span
130	      className={`relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-xl border border-white/10 ${className}`}
131	      style={{
132	        width: size,
133	        height: size,
134	        // Emoji tile gets the full brand gradient. A real logo needs CONTRAST:
135	        // most game wordmarks are DARK (Minecraft/Rust/Palworld/Terraria) and were
136	        // invisible on the old dark frosted tile — they sit on a LIGHT tile now.
137	        // The few LIGHT/white wordmarks (Valheim, CS2) keep a dark tile so they read.
138	        // Both carry a soft brand glow so the row still looks designed.
139	        background: exhausted
140	          ? `linear-gradient(135deg, ${visual.from}, ${visual.to})`
141	          : LIGHT_MARK.has(family)
142	            ? "rgba(9,14,28,0.9)"
143	            : "#eef2f8",
144	        boxShadow: `0 0 ${Math.round(size * 0.55)}px -${Math.round(size * 0.3)}px ${visual.to}`,
145	      }}
146	    >
147	      {exhausted ? (
148	        <span aria-hidden style={{ fontSize: Math.round(size * 0.5), lineHeight: 1 }}>
149	          {visual.glyph}
150	        </span>
151	      ) : (
152	        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
153	        <img
154	          key={src}
155	          src={src}
156	          alt={`${visual.name} logo`}
157	          onError={() => setIdx((i) => i + 1)}
158	          style={{
159	            width: size - pad * 2,
160	            height: size - pad * 2,
161	            objectFit: "contain",
162	          }}
163	        />
164	      )}
165	    </span>
166	  );
167	}
